{
  "witnessCode": "import { strict as assert } from 'node:assert';
import x from '../index.js';

const label = 'a'.repeat(63);
const url = `www.${label}.com`;

const baseResult = x(url, { stripWWW: true });
assert.ok(!baseResult.startsWith('www.'), 'Base should remove www. for 63‑char label');

const headResult = x(url, { stripWWW: true });
assert.ok(!headResult.startsWith('www.'), 'Head should also remove www. for 63‑char label');"
}
